local LeatherSkiverMaker = {}
local PRODUCTS = {
    iron_leatherskiver = { name = "Železni strgalec usnja", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni strgalec usnja za usnjarje." },
    bronze_leatherskiver = { name = "Bronast strgalec usnja", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast strgalec usnja za usnjarje." },
    silver_leatherskiver = { name = "Srebrn strgalec usnja", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn strgalec usnja za usnjarje." },
    gilded_leatherskiver = { name = "Pozlačen strgalec usnja", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen strgalec usnja za usnjarje." },
    jewel_set_leatherskiver = { name = "Draguljast strgalec usnja", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast strgalec usnja za usnjarje." },
    royal_sovereign_leatherskiver = { name = "Kraljevski suveren strgalec usnja", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren strgalec usnja z biseri za krono." },
}
local BUILDINGS = {
    leatherskiver_workshop = { name = "Leatherskiver delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    leatherskiver_house = { name = "Leatherskiver hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_leatherskiver_atelier = { name = "Mojstrski leatherskiver atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_leatherskiver_palace = { name = "Suverena leatherskiver palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
LeatherSkiverMaker.ironStock = 16; LeatherSkiverMaker.bronzeStock = 14; LeatherSkiverMaker.woodStock = 10; LeatherSkiverMaker.leatherStock = 10; LeatherSkiverMaker.silverStock = 8; LeatherSkiverMaker.goldStock = 6; LeatherSkiverMaker.jewelStock = 4; LeatherSkiverMaker.pearlStock = 4
LeatherSkiverMaker.productStock = {}; LeatherSkiverMaker.buildings = {}; LeatherSkiverMaker.maker = nil; LeatherSkiverMaker.activeMaking = {}; LeatherSkiverMaker.totalProducts = 0; LeatherSkiverMaker.dayTimer = 0
function LeatherSkiverMaker.init() LeatherSkiverMaker.ironStock=16; LeatherSkiverMaker.bronzeStock=14; LeatherSkiverMaker.woodStock=10; LeatherSkiverMaker.leatherStock=10; LeatherSkiverMaker.silverStock=8; LeatherSkiverMaker.goldStock=6; LeatherSkiverMaker.jewelStock=4; LeatherSkiverMaker.pearlStock=4; LeatherSkiverMaker.productStock={}; LeatherSkiverMaker.buildings={}; LeatherSkiverMaker.maker=nil; LeatherSkiverMaker.activeMaking={}; LeatherSkiverMaker.totalProducts=0; LeatherSkiverMaker.dayTimer=0; print("[LeatherSkiverMaker] Royal Leather Skiver Maker System initialized (6 products, 4 buildings)") end
function LeatherSkiverMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; LeatherSkiverMaker.maker={name=n or ("Strgalec "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Strgalec najet: %s (spretnost: %d)",LeatherSkiverMaker.maker.name,s),"success") end; return true end
function LeatherSkiverMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function LeatherSkiverMaker.build(id) local ok,e=LeatherSkiverMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(LeatherSkiverMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function LeatherSkiverMaker.getQualityBonus() local b=0; for _,bd in ipairs(LeatherSkiverMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function LeatherSkiverMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and LeatherSkiverMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and LeatherSkiverMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and LeatherSkiverMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and LeatherSkiverMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and LeatherSkiverMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and LeatherSkiverMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and LeatherSkiverMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and LeatherSkiverMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #LeatherSkiverMaker.buildings==0 then return false,"Potrebna strgalna delavnica" end; if not LeatherSkiverMaker.maker then return false,"Potreben strgalec" end; return true end
function LeatherSkiverMaker.make(pt,qty) qty=qty or 1; local ok,e=LeatherSkiverMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then LeatherSkiverMaker.ironStock=LeatherSkiverMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then LeatherSkiverMaker.bronzeStock=LeatherSkiverMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then LeatherSkiverMaker.woodStock=LeatherSkiverMaker.woodStock-d.woodCost*qty end; if d.leatherCost then LeatherSkiverMaker.leatherStock=LeatherSkiverMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then LeatherSkiverMaker.silverStock=LeatherSkiverMaker.silverStock-d.silverCost*qty end; if d.goldCost then LeatherSkiverMaker.goldStock=LeatherSkiverMaker.goldStock-d.goldCost*qty end; if d.jewelCost then LeatherSkiverMaker.jewelStock=LeatherSkiverMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then LeatherSkiverMaker.pearlStock=LeatherSkiverMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if LeatherSkiverMaker.maker then t=math.max(1,t-math.floor(LeatherSkiverMaker.maker.skill/13)) end; table.insert(LeatherSkiverMaker.activeMaking,{id="leatherskiver_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function LeatherSkiverMaker.completeMaking(m) local q=1.0+(LeatherSkiverMaker.getQualityBonus()/100); if LeatherSkiverMaker.maker then q=q+(LeatherSkiverMaker.maker.skill/140) end; q=math.min(2.5,q); LeatherSkiverMaker.productStock[m.productType]=(LeatherSkiverMaker.productStock[m.productType] or 0)+m.quantity; LeatherSkiverMaker.totalProducts=LeatherSkiverMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if LeatherSkiverMaker.maker then LeatherSkiverMaker.maker.itemsMade=LeatherSkiverMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then LeatherSkiverMaker.maker.skill=math.min(100,LeatherSkiverMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Strgalec izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"leatherskiver.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function LeatherSkiverMaker.update(dt) if not _G.state then return end; LeatherSkiverMaker.dayTimer=LeatherSkiverMaker.dayTimer+dt; if LeatherSkiverMaker.dayTimer>=30 then LeatherSkiverMaker.dayTimer=0; for i=#LeatherSkiverMaker.activeMaking,1,-1 do local m=LeatherSkiverMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then LeatherSkiverMaker.completeMaking(m); table.remove(LeatherSkiverMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(LeatherSkiverMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if LeatherSkiverMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function LeatherSkiverMaker.getStats() return {ironStock=LeatherSkiverMaker.ironStock,bronzeStock=LeatherSkiverMaker.bronzeStock,woodStock=LeatherSkiverMaker.woodStock,leatherStock=LeatherSkiverMaker.leatherStock,silverStock=LeatherSkiverMaker.silverStock,goldStock=LeatherSkiverMaker.goldStock,jewelStock=LeatherSkiverMaker.jewelStock,pearlStock=LeatherSkiverMaker.pearlStock,productStock=LeatherSkiverMaker.productStock,numBuildings=#LeatherSkiverMaker.buildings,hasMaker=LeatherSkiverMaker.maker~=nil,makerName=LeatherSkiverMaker.maker and LeatherSkiverMaker.maker.name or "—",makerSkill=LeatherSkiverMaker.maker and LeatherSkiverMaker.maker.skill or 0,activeMaking=#LeatherSkiverMaker.activeMaking,totalProducts=LeatherSkiverMaker.totalProducts} end
return LeatherSkiverMaker
